274	function saveToStorage(state: Partial<PersistedState>) {
275	  try {
276	    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
277	  } catch (e) {
278	    console.warn('[Knirvana] Could not persist state:', e);
279	  }
