350	/** Build a proposeSolution function that uses the GameLLMService */
351	function makeLLMProposer(): Agent['proposeSolution'] {
352	  return async (challenge: Challenge, persona: AgentPersona): Promise<SolutionProposal> => {
353	    const llm = getGameLLMService();
