713	    stageAgent: (agentId) => {
714	      const state = get();
715	      const agent = state.agents.find(a => a.id === agentId);
716	      if (!agent || agent.staged) return;
717	
718	      const stagedCount = state.agents.filter(a => a.staged).length;
719	      const stagingPos = getStagingPosition(stagedCount);
720	      const startPos = { ...agent.position };
721	      const startTime = Date.now();
722	      const duration = 1800;
723	
724	      // Mark as moving immediately
725	      set(s => ({
726	        agents: s.agents.map(a =>
727	          a.id === agentId ? { ...a, status: 'moving' as const } : a
728	        ),
729	      }));
730	
731	      const interval = setInterval(() => {
732	        const elapsed = Date.now() - startTime;
733	        const t = Math.min(elapsed / duration, 1);
734	        const eased = 1 - Math.pow(1 - t, 2);
735	
736	        if (t >= 1) {
737	          clearInterval(interval);
738	          set(s => ({
739	            agents: s.agents.map(a =>
740	              a.id === agentId
741	                ? { ...a, staged: true, status: 'idle' as const, target: null, position: stagingPos }
742	                : a
743	            ),
744	          }));
745	        } else {
746	          set(s => ({
747	            agents: s.agents.map(a =>
748	              a.id === agentId
749	                ? {
750	                    ...a,
751	                    position: {
752	                      x: startPos.x + (stagingPos.x - startPos.x) * eased,
753	                      y: 1,
754	                      z: startPos.z + (stagingPos.z - startPos.z) * eased,
755	                    },
756	                  }
757	                : a
758	            ),
759	          }));
760	        }
761	      }, 50);
762	    },
