779	    // ── Tournament epoch ──────────────────────────────────────────────────
780	
781	    runEpoch: async () => {
782	      const state = get();
783	      if (state.gamePhase !== 'playing') return;
784	
785	      const epochNumber = state.epochNumber + 1;
786	      set({ epochNumber });
787	
788	      // Pick the active error node that has a challenge
789	      const activeErrorNode = state.errorNodes.find(node => node.isBeingSolved && node.challengeId)
790	        ?? state.errorNodes.find(node => node.challengeId);
791	
792	      if (!activeErrorNode) {
793	        console.warn('[Tournament] No error nodes with challenges available');
794	        return;
795	      }
796	
797	      const challenge = CHALLENGES.find(c => c.id === activeErrorNode.challengeId)
798	        ?? CHALLENGES[epochNumber % CHALLENGES.length];
799	
800	      const llm = getGameLLMService();
801	      const personas = state.personas;
802	
803	      // Run all agents in parallel
804	      const agentResults = await Promise.all(
805	        state.agents.map(async (agent) => {
806	          const persona = personas.find(p => p.id === agent.personaId) ?? DEFAULT_PERSONAS[0];
807	
808	          const proposal = await agent.proposeSolution(challenge, persona);
809	          const evalResult = await llm.evaluate(challenge, proposal, persona);
810	
811	          return {
812	            agentId: agent.id,
813	            agentName: agent.name,
814	            personaId: persona.id,
815	            personaName: persona.name,
816	            proposal,
817	            score: evalResult.score,
818	            reasoning: evalResult.reasoning,
819	          };
820	        })
821	      );
822	
823	      // Rank by score
824	      const ranked = [...agentResults].sort((a, b) => b.score - a.score);
825	      const winner = ranked[0];
826	
827	      const epochResult: EpochResult = {
828	        epochNumber,
829	        challenge,
830	        agentResults,
831	        winnerId: winner?.agentId ?? null,
832	        winnerScore: winner?.score ?? 0,
833	        timestamp: Date.now(),
834	      };
835	
836	      // Update skill slot if winner beats incumbent
837	      let newSkillSlotOwner = state.skillSlotOwner;
838	      let newIncumbentScore = state.incumbentScore;
839	
840	      if (winner && winner.score > state.incumbentScore) {
841	        newSkillSlotOwner = winner.agentId;
842	        newIncumbentScore = winner.score;
843	        // Award extra NRN for hijacking the skill slot
844	        get().addNRN(Math.round(challenge.bounty * 1.5));
845	      }
846	
847	      // Update persona win rates
848	      const updatedPersonas = personas.map(persona => {
849	        const result = agentResults.find(r => r.personaId === persona.id);
850	        if (!result) return persona;
851	        const isWinner = result.agentId === winner?.agentId;
852	        const newTotal = persona.totalEpochs + 1;
853	        const newWins = persona.wins + (isWinner ? 1 : 0);
854	        return {
855	          ...persona,
856	          totalEpochs: newTotal,
857	          wins: newWins,
858	          winRate: newWins / newTotal,
859	        };
860	      });
861	
862	      set({
863	        lastEpochResult: epochResult,
864	        epochHistory: [...state.epochHistory.slice(-49), epochResult], // keep last 50
865	        skillSlotOwner: newSkillSlotOwner,
866	        incumbentScore: newIncumbentScore,
867	        personas: updatedPersonas,
868	      });
869	
870	      // Auto-save after each epoch
871	      get().saveProgress();
872	    },
873	
874	    // ── Sabotage ──────────────────────────────────────────────────────────
875	
876	    applySabotage: (targetAgentId, type, magnitude) => {
877	      const state = get();
878	      const targetAgent = state.agents.find(a => a.id === targetAgentId);
879	
880	      if (targetAgent) {
881	        const cost = magnitude * 10;
882	        if (state.spendNRN(cost)) {
883	          SabotageEngine.applyEffect(type, targetAgent, magnitude);
884	          set((s) => ({
885	            agents: s.agents.map(a =>
886	              a.id === targetAgentId ? { ...targetAgent } : a
887	            ),
888	          }));
889	        }
890	      }
891	    },
892	
893	    // ── Training ──────────────────────────────────────────────────────────
894	
895	    startTraining: (agentId) => {
896	      set({ gamePhase: 'training' });
897	      console.log(`[Training] Starting for agent ${agentId}`);
898	    },
899	
900	    distillTrajectory: (agentId) => {
901	      console.log(`[Training] Distilling trajectory for agent ${agentId}`);
902	    },
903	
904	    hardenAgent: (agentId) => {
905	      const state = get();
906	      const agent = state.agents.find(a => a.id === agentId);
907	      if (agent) {
908	        state.trainingManager.harden(agent);
909	        set((s) => ({
910	          agents: s.agents.map(a => a.id === agentId ? { ...agent } : a),
911	        }));
912	      }
913	    },
914	
915	    // ── Verifier controls ─────────────────────────────────────────────────
916	
917	    updateVerifierWeights: (weights) => {
918	      const state = get();
919	      state.verifier.updateWeights(weights);
920	    },
921	
922	    addVerifierConstraint: (id, validator) => {
923	      const state = get();
924	      state.verifier.addConstraint(id, validator);
925	    },
926	
927	    // ── Persona management ────────────────────────────────────────────────
928	
929	    updatePersona: (id, updates) => {
930	      set(state => ({
931	        personas: state.personas.map(p => p.id === id ? { ...p, ...updates } : p),
932	      }));
933	      get().saveProgress();
934	    },
935	
936	    addPersona: (persona) => {
937	      set(state => ({ personas: [...state.personas, persona] }));
938	      get().saveProgress();
939	    },
940	
941	    removePersona: (id) => {
942	      set(state => ({
943	        personas: state.personas.filter(p => p.id !== id),
944	      }));
945	      get().saveProgress();
946	    },
947	
948	    // ── Persistence ───────────────────────────────────────────────────────
949	
950	    saveProgress: () => {
951	      const state = get();
952	      saveToStorage({
953	        nrnBalance: state.nrnBalance,
954	        errorsResolved: state.errorsResolved,
955	        skillsLearned: state.skillsLearned,
956	        epochNumber: state.epochNumber,
957	        personas: state.personas,
958	        epochHistory: state.epochHistory.slice(-20), // save last 20 epochs
959	        incumbentScore: state.incumbentScore,
960	        skillSlotOwner: state.skillSlotOwner,
961	      });
962	    },
963	
964	    loadProgress: () => {
965	      const saved = loadFromStorage();
966	      if (Object.keys(saved).length > 0) {
967	        set({
968	          nrnBalance: saved.nrnBalance ?? 500,
969	          errorsResolved: saved.errorsResolved ?? 0,
970	          skillsLearned: saved.skillsLearned ?? 0,
971	          epochNumber: saved.epochNumber ?? 0,
972	          personas: saved.personas?.length ? saved.personas : DEFAULT_PERSONAS,
973	          epochHistory: saved.epochHistory ?? [],
974	          incumbentScore: saved.incumbentScore ?? 0.8,
975	          skillSlotOwner: saved.skillSlotOwner ?? null,
976	        });
977	      }
978	    },
979	
980	    // ── UI State ────────────────────────────────────────────────────────────
981	
982	    showAgentManagementModal: false,
983	    setShowAgentManagementModal: (show) => set({ showAgentManagementModal: show }),
984	    requestAgentManagementOpen: false,
985	    clearRequestAgentManagementOpen: () => set({ requestAgentManagementOpen: false }),
986	  }))
