101	  const resolvedErrors = errorNodes.filter(en => en.status === 'resolved');
102	  const totalRewards = errorNodes.reduce((sum, en) => sum + (en.status === 'resolved' ? en.nrnReward : 0), 0);
103	
104	  if (!isOpen) return null;
105	
106	  return (
107	    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
108	      <div className="w-full max-w-6xl max-h-[90vh] bg-slate-950 rounded-2xl border border-slate-800 shadow-2xl overflow-hidden">
109	        {/* Header */}
110	        <div className="sticky top-0 z-30 backdrop-blur supports-[backdrop-filter]:bg-slate-950/70 border-b border-slate-800">
111	          <div className="flex items-center justify-between px-6 py-4">
112	            <div className="flex items-center gap-3">
113	              <div className="p-2 rounded-2xl bg-gradient-to-br from-rose-500 to-orange-600 shadow-lg shadow-rose-800/30">
114	                <AlertTriangle className="w-6 h-6" />
115	              </div>
116	              <div>
117	                <h1 className="text-xl md:text-2xl font-semibold tracking-tight">Error Node Management</h1>
118	                <p className="text-xs text-slate-400">Monitor and resolve network errors</p>
119	              </div>
120	            </div>
121	            <button
122	              onClick={onClose}
123	              className="p-2 rounded-lg hover:bg-slate-800 transition-colors"
124	            >
125	              <span className="text-slate-400 text-xl">×</span>
126	            </button>
127	          </div>
128	        </div>
129	
130	        <div className="p-6">
131	          {/* Stats Overview */}
132	          <div className="grid grid-cols-4 gap-4 mb-6">
133	            <div className="p-4 rounded-xl border border-slate-800 bg-slate-900/60">
134	              <div className="flex items-center gap-2 mb-2">
135	                <AlertTriangle className="w-4 h-4 text-amber-400" />
136	                <span className="text-xs text-slate-400">Active</span>
137	              </div>
138	              <div className="text-xl font-bold text-slate-200">{activeErrors.length}</div>
139	            </div>
140	            
141	            <div className="p-4 rounded-xl border border-slate-800 bg-slate-900/60">
142	              <div className="flex items-center gap-2 mb-2">
143	                <Activity className="w-4 h-4 text-blue-400" />
144	                <span className="text-xs text-slate-400">Solving</span>
145	              </div>
146	              <div className="text-xl font-bold text-blue-400">{solvingErrors.length}</div>
147	            </div>
148	            
149	            <div className="p-4 rounded-xl border border-slate-800 bg-slate-900/60">
150	              <div className="flex items-center gap-2 mb-2">
151	                <CheckCircle className="w-4 h-4 text-emerald-400" />
152	                <span className="text-xs text-slate-400">Resolved</span>
153	              </div>
154	              <div className="text-xl font-bold text-emerald-400">{resolvedErrors.length}</div>
155	            </div>
156	            
157	            <div className="p-4 rounded-xl border border-slate-800 bg-slate-900/60">
158	              <div className="flex items-center gap-2 mb-2">
159	                <Zap className="w-4 h-4 text-yellow-400" />
160	                <span className="text-xs text-slate-400">Total Rewards</span>
161	              </div>
162	              <div className="text-xl font-bold text-yellow-400">{totalRewards} NRN</div>
163	            </div>
164	          </div>
165	
166	          <div className="grid grid-cols-12 gap-6">
167	            {/* Error Nodes List */}
168	            <div className="col-span-12 lg:col-span-8">
169	              <div className="space-y-4">
170	                <div className="flex items-center justify-between">
171	                  <h2 className="text-lg font-medium text-slate-200">Error Nodes</h2>
172	                  <div className="flex items-center gap-2 text-sm text-slate-400">
173	                    <span>{errorNodes.length} total</span>
174	                  </div>
175	                </div>
176	                
177	                <div className="space-y-3 max-h-96 overflow-y-auto">
178	                  {errorNodes.map((errorNode) => {
179	                    const StatusIcon = getStatusIcon(errorNode.status);
180	                    return (
