367	        {/* Rendered here, OUTSIDE overflow-hidden, so its fixed inset-0
368	            header bar (Back / X buttons) is not clipped by the content area. */}
369	        <DVEWorkspaceExplorer
370	          isOpen={showVerification}
371	          onClose={() => setShowVerification(false)}
372	          dveId={actualNodeId}
373	          dveName={actualNodeName}
374	          initialTab="files"
375	        />
376	      </div>
377	    </div>,
378	    document.body
379	  );
380	};
381	
382	export default DVEWorkspacePanel;
