pushToast: (text, tone = 'info') => {
  const id = `toast-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
  set(s => ({ toasts: [...s.toasts.slice(-3), { id, text, tone }] }));
  setTimeout(() => get().dismissToast(id), 4500);
},

dismissToast: (id) => {
  set(s => ({ toasts: s.toasts.filter(t => t.id !== id) }));
},

